def _fields(line):
    fields = []
    cur = []
    in_quote = False
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if in_quote:
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    cur.append('"')
                    i += 1
                else:
                    in_quote = False
            else:
                cur.append(c)
        elif c == '"':
            in_quote = True
        elif c == ',':
            fields.append(''.join(cur))
            cur = []
        else:
            cur.append(c)
        i += 1
    fields.append(''.join(cur))
    return fields


def rows(text):
    for line in text.splitlines()[1:]:
        yield _fields(line)

